const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const config={crew:'female',concept:'fierce'};
const themes={fierce:{accent:'#ff58ab',song:'PINK VENOM',color:'#f9e3f2',outfit:'#e93283'},bright:{accent:'#ffc857',song:'SUNNY SIDE',color:'#ffe9a8',outfit:'#ff9c42'},dark:{accent:'#aa83ff',song:'MOONLIGHT',color:'#ddd5ff',outfit:'#5740a7'},dreamy:{accent:'#63dff0',song:'STARLIGHT',color:'#cdfaff',outfit:'#53b6cf'},royal:{accent:'#ffd76d',song:'CROWN ME',color:'#fff0c1',outfit:'#b38b39'}};
const keys=['d','f','j','k']; let game={playing:false,paused:false,elapsed:0,score:0,combo:0,maxCombo:0,perfect:0,good:0,misses:0,notes:[],spawned:0,raf:0,last:0};
let audio=null,master=null,bgTimer=null,beatCount=0; const SONG_LEN=57,TRAVEL=1.65,BPM=116,BEAT=60/BPM;
function makeDancers(target,crew){const arr=crew==='mixed'?['#e6ad8d','#bb806f','#efbd9a','#9d6658']:crew==='male'?['#d39b7b','#b97861','#efba95','#aa765c']:['#e9b69a','#bd826e','#f2c5a6','#9f6a60'];target.innerHTML=arr.map((skin,i)=>`<div class="dancer" style="--skin:${skin};--fit:${themes[config.concept].outfit};--hair:${['#251525','#321b28','#171627','#39202d'][i]}"><i class="arm left"></i><i class="arm right"></i><i class="head"></i><i class="body-d"></i><i class="legs"></i></div>`).join('')}
function setConcept(value){config.concept=value;const t=themes[value];document.documentElement.style.setProperty('--stage-accent',t.accent);makeDancers($('#previewDancers'),config.crew);makeDancers($('#gameDancers'),config.crew);$('.game-stage').style.setProperty('--stage-accent',t.accent);$('#songName').textContent=t.song;$('#songConcept').textContent=value.toUpperCase()+' CONCEPT';$$('#conceptChoices .choice').forEach(b=>b.classList.toggle('selected',b.dataset.value===value));}
function setCrew(value){config.crew=value;$$('#crewChoices .choice').forEach(b=>b.classList.toggle('selected',b.dataset.value===value));makeDancers($('#previewDancers'),value);makeDancers($('#gameDancers'),value);}
$$('#crewChoices .choice').forEach(b=>b.onclick=()=>setCrew(b.dataset.value));$$('#conceptChoices .choice').forEach(b=>b.onclick=()=>setConcept(b.dataset.value));
function showScreen(id){$$('.screen').forEach(s=>s.classList.toggle('active',s.id===id));window.scrollTo({top:0,behavior:'smooth'})}
$('#debutBtn').onclick=()=>{showScreen('game');$('#groupLabel').textContent=(config.crew==='mixed'?'MIXED CREW':config.crew.toUpperCase()+' GROUP')+' · '+config.concept.toUpperCase();$('#startOverlay').classList.remove('hidden')};
$('#backBtn').onclick=()=>{stopGame();showScreen('setup')};
function buildChart(){const patterns=[[0,2,1,3],[1,0,3,2],[0,1,2,3],[3,1,0,2],[2,0,1,3],[1,3,2,0],[0,2,3,1],[2,1,3,0]];const notes=[];let beat=4,step=0;while(beat*BEAT<SONG_LEN-1){const bar=Math.floor(step/4);const pattern=patterns[(bar+Math.floor(bar/3))%patterns.length];const lane=pattern[step%4];notes.push({time:beat*BEAT,lane,hit:false,spawned:false});if(step%8===5&&bar%2===1)notes.push({time:beat*BEAT+BEAT*.5,lane:(lane+2+(bar%2))%4,hit:false,spawned:false});step++;beat+=1}return notes.sort((a,b)=>a.time-b.time)}
function resetGame(){game={playing:false,paused:false,elapsed:0,score:0,combo:0,maxCombo:0,perfect:0,good:0,misses:0,notes:buildChart(),spawned:0,raf:0,last:0};$$('.note').forEach(n=>n.remove());$$('.feedback').forEach(n=>n.remove());$('#score').textContent='000000';$('#combo').textContent='0';$('#rank').textContent='C';$('#progressFill').style.width='0%';$('#timeLabel').textContent='0:00 / 0:57';$('#songProgressLabel').textContent='SHOW STARTING';$('#startOverlay').classList.remove('hidden');$('#pauseOverlay').classList.add('hidden');$('#resultOverlay').classList.add('hidden');$('#pauseBtn').classList.remove('hidden');$('#restartBtn').classList.add('hidden');}
function startGame(){resetGame();initAudio();game.playing=true;game.last=performance.now();$('#startOverlay').classList.add('hidden');$('#songProgressLabel').textContent='NOW PERFORMING';$('#pauseBtn').classList.remove('hidden');runFrame();startBacking()}
$('#startBtn').onclick=startGame;$('#replayBtn').onclick=startGame;
function initAudio(){try{if(!audio){audio=new(window.AudioContext||window.webkitAudioContext)();master=audio.createGain();master.gain.value=Number($('#volume').value)/100*.3;master.connect(audio.destination)}if(audio.state==='suspended')audio.resume()}catch(e){}}
$('#volume').oninput=e=>{if(master)master.gain.setTargetAtTime(Number(e.target.value)/100*.3,audio.currentTime,.03)};
function tone(freq,duration=.11,wave='sine',volume=.25){if(!audio||!master)return;const now=audio.currentTime,osc=audio.createOscillator(),gain=audio.createGain();osc.type=wave;osc.frequency.setValueAtTime(freq,now);gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(volume,now+.012);gain.gain.exponentialRampToValueAtTime(.0001,now+duration);osc.connect(gain);gain.connect(master);osc.start(now);osc.stop(now+duration+.02)}
function startBacking(){stopBacking();beatCount=0;bgTimer=setInterval(()=>{if(!game.playing||game.paused)return;const base=[130.81,146.83,110,164.81][Math.floor(game.elapsed/7)%4];if(beatCount%4===0)tone(base,.34,'triangle',.13);else if(beatCount%2===0)tone(base*2,.09,'sine',.045);beatCount++},BEAT*1000)}function stopBacking(){if(bgTimer){clearInterval(bgTimer);bgTimer=null}}
function runFrame(now=performance.now()){if(!game.playing)return;if(!game.paused){const dt=Math.min(.06,(now-game.last)/1000);game.elapsed+=dt;game.last=now;updateFrame()}else game.last=now;game.raf=requestAnimationFrame(runFrame)}
function updateFrame(){const stage=$('#gameStage'),target=stage.clientHeight-77;for(const note of game.notes){if(!note.spawned&&game.elapsed>=note.time-TRAVEL){note.spawned=true;note.el=document.createElement('div');note.el.className='note';note.el.style.left=`calc(${12.5+25*note.lane}% - 26px)`;note.el.dataset.lane=note.lane;$('#lanes').appendChild(note.el)}if(note.spawned&&note.el&&!note.hit){const y=-22+(target+22)*((game.elapsed-(note.time-TRAVEL))/TRAVEL);note.el.style.top=`${y}px`;if(game.elapsed>note.time+.2)missNote(note)}}
const pct=Math.min(100,game.elapsed/SONG_LEN*100);$('#progressFill').style.width=pct+'%';$('#timeLabel').textContent=`${formatTime(game.elapsed)} / 0:57`;const rank=calcRank();$('#rank').textContent=rank; if(game.elapsed>=SONG_LEN){finishGame();}}
function formatTime(s){s=Math.min(57,Math.floor(s));return`0:${String(s).padStart(2,'0')}`}
function calcRank(){const total=game.perfect+game.good+game.misses;if(!total)return'C';const ratio=(game.perfect+game.good*.65)/total;return ratio>=.97?'S':ratio>=.88?'A':ratio>=.72?'B':ratio>=.55?'C':'D'}
function missNote(note){if(note.hit)return;note.hit=true;game.combo=0;game.misses++;note.el?.classList.add('miss');setTimeout(()=>note.el?.remove(),220);$('#combo').textContent='0';$('#songProgressLabel').textContent='KEEP GOING';feedback('MISS','miss');updateScore()}
function hitLane(lane){if(!game.playing||game.paused)return;const pad=$(`.hit-pad[data-lane="${lane}"]`);pad?.classList.add('pressed');$$(`.mobile-keys [data-hit="${lane}"]`).forEach(b=>b.classList.add('pressed'));setTimeout(()=>{pad?.classList.remove('pressed');$$(`.mobile-keys [data-hit="${lane}"]`).forEach(b=>b.classList.remove('pressed'))},110);$('.lane[data-lane="'+lane+'"]')?.classList.add('active');setTimeout(()=>$('.lane[data-lane="'+lane+'"]')?.classList.remove('active'),170);
let best=null,diff=1;for(const note of game.notes){if(note.hit||note.lane!==lane)continue;const d=Math.abs(note.time-game.elapsed);if(d<diff){best=note;diff=d}}if(!best||diff>.2){tone(190,.045,'triangle',.05);return}best.hit=true;best.el?.classList.add('hit');setTimeout(()=>best.el?.remove(),230);if(diff<=.085){game.perfect++;game.score+=1000+game.combo*6;feedback('PERFECT','perfect');tone([523.25,659.25,783.99,1046.5][lane],.13,'sine',.21)}else{game.good++;game.score+=500+game.combo*3;feedback('GOOD','good');tone([392,493.88,587.33,698.46][lane],.11,'triangle',.18)}game.combo++;game.maxCombo=Math.max(game.combo,game.maxCombo);$('#combo').textContent=game.combo;updateScore()}
function feedback(text,cls){const old=$('.feedback');if(old)old.remove();const el=document.createElement('div');el.className='feedback '+cls;el.textContent=text;$('#lanes').appendChild(el);setTimeout(()=>el.remove(),700)}function updateScore(){$('#score').textContent=String(game.score).padStart(6,'0');$('#rank').textContent=calcRank()}
$$('.hit-pad').forEach(el=>el.addEventListener('pointerdown',e=>{e.preventDefault();hitLane(Number(el.dataset.lane))}));$$('.mobile-keys button').forEach(el=>el.addEventListener('pointerdown',e=>{e.preventDefault();hitLane(Number(el.dataset.hit))}));$$('.lane').forEach(el=>el.addEventListener('pointerdown',()=>hitLane(Number(el.dataset.lane))));document.addEventListener('keydown',e=>{const lane=keys.indexOf(e.key.toLowerCase());if(lane>=0&&!e.repeat){e.preventDefault();hitLane(lane)}if(e.key==='Escape'||e.key.toLowerCase()==='p'){if(game.playing)togglePause()}});
function togglePause(){if(!game.playing)return;game.paused=!game.paused;if(game.paused){$('#pauseOverlay').classList.remove('hidden');$('#songProgressLabel').textContent='SHOW PAUSED'}else{$('#pauseOverlay').classList.add('hidden');game.last=performance.now();$('#songProgressLabel').textContent='NOW PERFORMING'}}$('#pauseBtn').onclick=togglePause;$('#resumeBtn').onclick=togglePause;
$('#restartBtn').onclick=startGame;
function finishGame(){game.playing=false;stopBacking();$('#resultOverlay').classList.remove('hidden');$('#resultRank').textContent=calcRank();$('#resultScore').textContent=game.score.toLocaleString();$('#resultMaxCombo').textContent=game.maxCombo;$('#resultPerfect').textContent=game.perfect;const r=calcRank();$('#resultTitle').textContent=r==='S'?'You owned that stage!':r==='A'?'A star is born!':'The crowd loved you!';$('#resultMessage').textContent=`${game.perfect} perfect hits · ${game.misses} missed beats`;$('#progressFill').style.width='100%';$('#songProgressLabel').textContent='SHOW COMPLETE';$('#pauseBtn').classList.add('hidden');$('#restartBtn').classList.remove('hidden')}
function stopGame(){game.playing=false;cancelAnimationFrame(game.raf);stopBacking();resetGame()}
setCrew('female');setConcept('fierce');
</script>

